// ---------------------------------------------------------------------------
// Formulario del Gate · Preparar la ficha del caso (página 2).
// Entrada ($json): la respuesta COMPLETA de GET /gate-avisos/{id}, es decir
//   { statusCode, headers, body } (opción "Include Response Headers and Status").
// Salida: { resultado, mensaje, ficha_html, oportunidad_id }, donde resultado es:
//   'ok'          -> el caso se puede registrar: se muestra la ficha
//   'ya_decidido' -> el caso ya tiene decisión: se termina con un aviso
//   'error'       -> el backend no lo permite: se termina explicando por qué
// Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Código HTTP de la respuesta (200, 404, 409...) y su cuerpo. "?? {}": si no
// hubiera cuerpo, un objeto vacío, para que las líneas de abajo no fallen.
const estado = $json.statusCode;
const b = $json.body ?? {};

// Escapar el texto antes de meterlo en HTML: el nombre, el email... los
// escribió el CLIENTE en el chat (mismo motivo que en el email de WF2).
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ---- 1. Respuestas que NO son 200: explicar el motivo y terminar ------------
// Mensajes para administración según el "motivo" que devuelve el backend en
// sus errores de negocio: {"detail": {"motivo": "...", "mensaje": "..."}}.
const MENSAJES_MOTIVO = {
  oportunidad_no_encontrada: 'No existe ninguna oportunidad con ese número. Revisa el número del aviso.',
  sin_presupuesto: 'Esa oportunidad todavía no tiene presupuesto calculado.',
  sin_gate: 'Esa oportunidad no tiene Gate: no hace falta registrar ninguna llamada.',
};

if (estado !== 200) {
  // "?." evita romper si detail no es un objeto (un 422 trae una lista).
  let mensaje = MENSAJES_MOTIVO[b.detail?.motivo];
  // Si el motivo no está en la lista, se explica según el código HTTP.
  if (!mensaje) {
    if (estado === 422) {
      mensaje = 'El número de oportunidad no es válido.';
    } else if (estado === 401) {
      mensaje = 'Error de configuración: el formulario no tiene una llave válida. Avisa al responsable técnico.';
    } else {
      mensaje = `Error inesperado del sistema (código ${estado}). Inténtalo de nuevo en unos minutos.`;
    }
  }
  return { json: { resultado: 'error', mensaje, ficha_html: '', oportunidad_id: null } };
}

// ---- 2. Respuesta 200: preparar los datos del caso --------------------------
const c = b.contacto;      // nombre, email, telefono y origen
const r = b.reforma;       // tipo, m2, acabados y cambios estructurales
const p = b.presupuesto;   // importes y motivo del Gate

// Formatos españoles, solo para MOSTRAR.
const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
const num = new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2 });
function dinero(t) { return (t === null || t === undefined) ? '—' : eur.format(Number(t)); }
function fecha(t) {
  if (!t) return '—';
  return new Date(t).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}

// Diccionarios: códigos del backend -> texto legible (los mismos que en WF2).
const TIPOS = {
  bano: 'Baño', cocina: 'Cocina', integral_vivienda: 'Reforma integral de vivienda',
  parcial_acabados: 'Acabados parciales',
};
const ACABADOS = { basico: 'Básico', medio: 'Medio', alto: 'Alto' };
const MOTIVOS = {
  cambios_estructurales: 'Cambios estructurales',
  importe_superior_umbral: 'Importe superior al umbral',
  ambos: 'Cambios estructurales e importe superior al umbral',
};
const DECISIONES = { visita_acordada: 'Visita acordada', descartar: 'Descartado' };
// NUEVO (2026-10-06): motivos de descarte del backend -> texto legible
// (los mismos que en traducir_resultado).
const MOTIVOS_DESCARTE = {
  precio: 'precio', plazo: 'plazo', no_contesta: 'no contesta',
  proyecto_no_viable: 'proyecto no viable', otro: 'otro',
};

// ---- 3. ¿Ya tiene decisión? Entonces no se puede registrar otra -------------
// La decisión es definitiva (D21.5): el backend respondería 409 a una
// distinta. Se avisa aquí, antes de que administración rellene nada.
if (b.decision) {
  const d = b.decision;
  // Visita: se enseña la fecha; descarte: el motivo en castellano.
  // "?? d.motivo": si apareciera un motivo nuevo, se enseña el código tal cual.
  const detalle = d.decision === 'visita_acordada'
    ? `visita el ${fecha(d.fecha_visita)}`
    : `motivo: ${MOTIVOS_DESCARTE[d.motivo] ?? d.motivo}`;
  return {
    json: {
      resultado: 'ya_decidido',
      mensaje:
        `La oportunidad ${b.oportunidad_id} ya tiene una decisión registrada ` +
        `(${DECISIONES[d.decision] ?? d.decision}, ${detalle}; registrada el ${fecha(d.fecha_decision)}). ` +
        `La decisión es definitiva: no hace falta volver a registrarla.`,
      ficha_html: '',
      oportunidad_id: b.oportunidad_id,
    },
  };
}

// ---- 4. La ficha del caso en HTML -------------------------------------------
// Una fila "etiqueta: valor". El valor SIEMPRE pasa por esc().
function fila(etiqueta, valor) {
  return `<tr><td style="padding:4px 12px 4px 0;color:#5B6B79;">${etiqueta}</td>` +
         `<td style="padding:4px 0;font-weight:bold;">${esc(valor)}</td></tr>`;
}

// Contacto: el de esta solicitud, o un aviso si es un lead antiguo (P1).
const filasContacto = c.origen === 'solicitud'
  ? fila('Cliente', c.nombre ?? '—') + fila('Teléfono', c.telefono ?? '—')
  : fila('Contacto', 'No disponible (lead anterior al 25/09/2026)');

const ficha_html =
  `<div style="border-left:4px solid #1F8A8A;background:#E3F2F1;padding:12px 16px;border-radius:6px;">` +
  `<div style="font-weight:bold;color:#0B3C5D;margin-bottom:6px;">Oportunidad ${esc(b.oportunidad_id)}</div>` +
  `<table>` +
  filasContacto +
  fila('Reforma', `${TIPOS[r.tipo_reforma] ?? r.tipo_reforma ?? '—'}, ${num.format(Number(r.m2))} m², acabado ${ACABADOS[r.nivel_acabados] ?? r.nivel_acabados ?? '—'}`) +
  fila('Motivo del Gate', MOTIVOS[p.motivo_gate] ?? p.motivo_gate ?? '—') +
  fila('Horquilla (IVA incl.)', `${dinero(p.importe_min_con_iva)} – ${dinero(p.importe_max_con_iva)}`) +
  `</table></div>`;

// ---- 5. Salida: todo listo para la página del resultado ---------------------
return { json: { resultado: 'ok', mensaje: '', ficha_html, oportunidad_id: b.oportunidad_id } };

// ---------------------------------------------------------------------------
// Formulario del Gate · Preparar la decisión (después de la página 3).
// Entrada ($json): lo rellenado en pagina_visita O en pagina_descarte.
// Salida: { valido, mensaje, cuerpo, resumen_html }
//   valido       -> true si todo cuadra; false = no se envía nada
//   mensaje      -> explicación cuando valido es false
//   cuerpo       -> el JSON EXACTO que irá a POST /gate-decisions
//   resumen_html -> el resumen para la página de confirmación
// Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Número de oportunidad: lo dejó preparar_ficha (viene del backend, no del usuario).
const oportunidad_id = $('preparar_ficha').item.json.oportunidad_id;
// Lo elegido en la página 2: 'Visita acordada' o 'Descartar'.
const eleccion = $('pagina_resultado').item.json.decision;

// Textos del desplegable -> valores que admite el backend (CHECK + Enum MotivoDescarte).
const MOTIVOS = {
  'Precio: le parece caro': 'precio',
  'Plazo: no le encajan los tiempos': 'plazo',
  'No contesta (tras varios intentos)': 'no_contesta',
  'Proyecto no viable técnicamente': 'proyecto_no_viable',
  'Otro (explícalo en el informe)': 'otro',
};

// Salida de error: se usa cuando algo no cuadra; así no se envía nada al backend.
function invalido(mensaje) {
  return { json: { valido: false, mensaje, cuerpo: null, resumen_html: '' } };
}

// Escapar texto antes de meterlo en HTML (mismo motivo que en preparar_ficha).
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Una fila "etiqueta: valor" del resumen. El valor SIEMPRE pasa por esc().
function fila(etiqueta, valor) {
  return `<tr><td style="padding:4px 12px 4px 0;color:#5B6B79;vertical-align:top;">${etiqueta}</td>` +
         `<td style="padding:4px 0;font-weight:bold;">${esc(valor)}</td></tr>`;
}

// Sin número de oportunidad no hay nada que registrar.
if (!oportunidad_id) return invalido('No se ha podido recuperar el número de oportunidad. Vuelve a abrir el formulario.');

// El informe sin espacios ni saltos de línea sobrantes al principio y al final.
const informe = String($json.informe ?? '').trim();
// El backend exige de 1 a 2.000 caracteres: se avisa aquí con un mensaje claro.
if (informe.length === 0) return invalido('El informe de la llamada está vacío.');
if (informe.length > 2000) return invalido(`El informe tiene ${informe.length} caracteres; el máximo es 2.000.`);

let cuerpo;   // el JSON para el backend
let filas;    // las filas del resumen que verá el operador

if (eleccion === 'Visita acordada') {
  // '2026-10-12' -> año, mes y día por separado, para mostrarlo en formato español.
  const [a, m, d] = String($json.fecha).split('-');
  // Día de la semana, para que el operador detecte un error de fecha antes de confirmar.
  // Date.UTC + getUTCDay: así la zona horaria del servidor no puede mover el día.
  const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
  const diaSemana = DIAS[new Date(Date.UTC(Number(a), Number(m) - 1, Number(d))).getUTCDay()];
  // Visita: fecha y hora obligatorias, sin motivo (el backend daría 422 si no).
  cuerpo = { oportunidad_id, decision: 'visita_acordada', fecha: $json.fecha, hora: $json.hora, informe };
  filas = fila('Decisión', 'Visita acordada') +
          fila('Fecha', `${diaSemana} ${d}/${m}/${a}`) +
          fila('Hora', $json.hora);
} else if (eleccion === 'Descartar') {
  // Traducir el texto del desplegable al valor del backend.
  const motivo = MOTIVOS[$json.motivo];
  // Si el texto del desplegable no coincide con el diccionario, mejor parar que adivinar.
  if (!motivo) return invalido(`Motivo no reconocido: "${$json.motivo}". Avisa al responsable técnico.`);
  // Descartar: motivo obligatorio, sin fecha ni hora.
  cuerpo = { oportunidad_id, decision: 'descartar', motivo, informe };
  filas = fila('Decisión', 'DESCARTAR (definitivo)') + fila('Motivo', $json.motivo);
} else {
  // Ni una cosa ni la otra: no se envía nada.
  return invalido(`Decisión no reconocida: "${eleccion}". Avisa al responsable técnico.`);
}

// El informe, escapado y con sus saltos de línea convertidos en <br>.
const informeHtml = esc(informe).replace(/\r?\n/g, '<br>');

// El resumen completo, con el mismo estilo que la ficha de la página 2.
const resumen_html =
  `<div style="border-left:4px solid #1F8A8A;background:#E3F2F1;padding:12px 16px;border-radius:6px;">` +
  `<div style="font-weight:bold;color:#0B3C5D;margin-bottom:6px;">Oportunidad ${esc(oportunidad_id)}</div>` +
  `<table>` + filas +
  `<tr><td style="padding:4px 12px 4px 0;color:#5B6B79;vertical-align:top;">Informe</td>` +
  `<td style="padding:4px 0;">${informeHtml}</td></tr>` +
  `</table></div>`;

// Todo listo: el cuerpo para el envío y el resumen para confirmar.
return { json: { valido: true, mensaje: '', cuerpo, resumen_html } };

// ---------------------------------------------------------------------------
// Formulario del Gate · Traducir la respuesta de POST /gate-decisions.
// Entrada ($json): la respuesta COMPLETA { statusCode, headers, body }.
// Salida: { titulo, mensaje } para la pantalla final (texto plano).
// Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------

// Código HTTP y cuerpo de la respuesta ("?? {}": objeto vacío si no hay cuerpo).
const estado = $json.statusCode;
const b = $json.body ?? {};
// Número de oportunidad: del cuerpo que se envió (por si la respuesta no lo trae).
const op = $('preparar_decision').item.json.cuerpo.oportunidad_id;

// Fecha y hora en formato español y hora de Madrid, solo para MOSTRAR.
function fecha(t) {
  if (!t) return '—';
  return new Date(t).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid', weekday: 'long', day: '2-digit', month: '2-digit',
    year: 'numeric', hour: '2-digit', minute: '2-digit',
  });
}

// Atajo para devolver la pantalla final.
function pantalla(titulo, mensaje) {
  return { json: { titulo, mensaje } };
}

// Motivos del backend (fijos) -> textos para el operador.
const MOTIVOS_DESCARTE = {
  precio: 'precio', plazo: 'plazo', no_contesta: 'no contesta',
  proyecto_no_viable: 'proyecto no viable', otro: 'otro',
};

// ---- 1. Éxito: 201 (registrada ahora) o 200 (ya estaba registrada igual) ----
if (estado === 201 || estado === 200) {
  // 201 = se ha creado ahora; 200 = repetición exacta: el backend no ha escrito nada.
  const nueva = estado === 201;
  if (b.decision === 'visita_acordada') {
    return pantalla(
      nueva ? 'Visita registrada' : 'La visita ya estaba registrada',
      `Oportunidad ${op}: visita el ${fecha(b.fecha_propuesta)} (registro nº ${b.decision_id}). ` +
      (nueva
        // Fase 1: el evento del calendario todavía no se crea solo (llegará con la Fase 2).
        ? 'La oportunidad pasa a "visita agendada". Anota la visita en el calendario "Visitas técnicas — Reformas Amedida".'
        : 'No se ha cambiado nada.'),
    );
  }
  return pantalla(
    nueva ? 'Descarte registrado' : 'El descarte ya estaba registrado',
    `Oportunidad ${op} descartada, motivo: ${MOTIVOS_DESCARTE[b.motivo] ?? b.motivo} (registro nº ${b.decision_id}). ` +
    (nueva ? 'La oportunidad queda cerrada como perdida.' : 'No se ha cambiado nada.'),
  );
}

// ---- 2. Rechazos de negocio: {"detail": {"motivo": ..., "mensaje": ...}} -----
// "?." evita romper si detail no es un objeto (un 422 de forma trae una lista).
const motivo = b.detail?.motivo;

// Fecha u hora no válidas: el mensaje del backend ya explica la regla y las franjas.
if (estado === 422 && motivo) {
  return pantalla('Fecha u hora no válidas',
    `${b.detail.mensaje} No se ha registrado nada: vuelve a abrir el formulario y elige otra fecha u hora.`);
}

// Conflictos (409) y oportunidad inexistente (404): textos propios para cada motivo.
const MENSAJES = {
  decision_ya_registrada: 'Esta oportunidad ya tiene otra decisión registrada. La decisión es definitiva: no se ha cambiado nada.',
  estado_no_permitido: 'El estado actual de la oportunidad no permite registrar una decisión (puede que ya esté cerrada). No se ha registrado nada.',
  visita_activa_existente: 'La oportunidad ya tiene una visita activa. No se ha registrado nada; revisa el caso con el responsable técnico.',
  sin_gate: 'Esta oportunidad no tiene Gate: no hace falta registrar ninguna llamada.',
  sin_presupuesto: 'Esta oportunidad no tiene presupuesto calculado. No se ha registrado nada.',
  oportunidad_no_encontrada: 'No existe ninguna oportunidad con ese número. No se ha registrado nada.',
};
if (MENSAJES[motivo]) return pantalla('No se ha podido registrar', MENSAJES[motivo]);

// ---- 3. Errores técnicos: el operador no puede arreglarlos, solo avisar ------
if (estado === 401) {
  return pantalla('Error de configuración', 'El formulario no tiene una llave válida. No se ha registrado nada. Avisa al responsable técnico.');
}
if (estado === 422) {
  // 422 sin motivo = el cuerpo no tiene la forma esperada: fallo nuestro, no del operador.
  return pantalla('Error en los datos enviados', 'El sistema ha rechazado el formato de los datos. No se ha registrado nada. Avisa al responsable técnico.');
}
if (estado === 503) {
  return pantalla('Sistema sin configurar', 'Falta configuración de las reglas de visita. No se ha registrado nada. Avisa al responsable técnico.');
}
// Cualquier otro código: se enseña para que el responsable técnico pueda buscarlo.
return pantalla('Error inesperado', `Código ${estado}. No se ha registrado nada. Avisa al responsable técnico.`);
